    {
        if (auto vrrpLayer = dynamic_cast<pcpp::VrrpLayer*>(layer))
        {
            vrrpLayer->getIPAddresses();
            vrrpLayer->isChecksumCorrect();
            vrrpLayer->getChecksum();
            vrrpLayer->getPriorityAsEnum();
            vrrpLayer->getPriority();
            vrrpLayer->getType();
        }
    }
